class Solution:
    def findContestMatch(self, n: int) -> str:
        teams = [str(i) for i in range(1, n + 1)]
        while len(teams) > 1:
            teams = [f"({teams[i]},{teams[-1-i]})" for i in range(len(teams) // 2)]
        return teams[0]

import java.util.*;
class Solution {
    public String findContestMatch(int n) {
        List<String> teams = new ArrayList<>();
        for (int i = 1; i <= n; i++) teams.add(Integer.toString(i));
        while (teams.size() > 1) {
            List<String> next = new ArrayList<>();
            for (int i = 0; i < teams.size() / 2; i++) next.add("(" + teams.get(i) + "," + teams.get(teams.size() - 1 - i) + ")");
            teams = next;
        }
        return teams.get(0);
    }
}

class Solution:
    def findCircleNum(self, isConnected: list[list[int]]) -> int:
        n = len(isConnected)
        seen = set()
        provinces = 0
        for start in range(n):
            if start in seen:
                continue
            provinces += 1
            stack = [start]
            seen.add(start)
            while stack:
                u = stack.pop()
                for v, connected in enumerate(isConnected[u]):
                    if connected and v not in seen:
                        seen.add(v)
                        stack.append(v)
        return provinces

class Solution {
    public int findCircleNum(int[][] isConnected) {
        int n = isConnected.length, provinces = 0;
        boolean[] seen = new boolean[n];
        for (int start = 0; start < n; start++) {
            if (seen[start]) continue;
            provinces++;
            Deque<Integer> stack = new ArrayDeque<>();
            stack.push(start); seen[start] = true;
            while (!stack.isEmpty()) {
                int u = stack.pop();
                for (int v = 0; v < n; v++) if (isConnected[u][v] == 1 && !seen[v]) { seen[v] = true; stack.push(v); }
            }
        }
        return provinces;
    }
}

class Solution:
    def checkRecord(self, s: str) -> bool:
        return s.count('A') < 2 and 'LLL' not in s

class Solution {
    public boolean checkRecord(String s) {
        int absences = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == 'A' && ++absences >= 2) return false;
            if (i >= 2 && s.charAt(i) == 'L' && s.charAt(i - 1) == 'L' && s.charAt(i - 2) == 'L') return false;
        }
        return true;
    }
}

class Solution:
    def optimalDivision(self, nums: list[int]) -> str:
        if len(nums) == 1:
            return str(nums[0])
        if len(nums) == 2:
            return f"{nums[0]}/{nums[1]}"
        return str(nums[0]) + "/(" + "/".join(map(str, nums[1:])) + ")"

class Solution {
    public String optimalDivision(int[] nums) {
        if (nums.length == 1) return Integer.toString(nums[0]);
        if (nums.length == 2) return nums[0] + "/" + nums[1];
        StringBuilder out = new StringBuilder().append(nums[0]).append("/(");
        for (int i = 1; i < nums.length; i++) { if (i > 1) out.append('/'); out.append(nums[i]); }
        return out.append(')').toString();
    }
}

class Solution:
    def reverseWords(self, s: str) -> str:
        return ' '.join(word[::-1] for word in s.split(' '))

class Solution {
    public String reverseWords(String s) {
        String[] words = s.split(" ", -1);
        for (int i = 0; i < words.length; i++) words[i] = new StringBuilder(words[i]).reverse().toString();
        return String.join(" ", words);
    }
}

class Solution:
    def maxDepth(self, root) -> int:
        if root is None:
            return 0
        return 1 + max((self.maxDepth(child) for child in root.children), default=0)

class Solution {
    public int maxDepth(Node root) {
        if (root == null) return 0;
        int best = 0;
        for (Node child : root.children) best = Math.max(best, maxDepth(child));
        return best + 1;
    }
}

class Solution:
    def subarraySum(self, nums: list[int], k: int) -> int:
        freq = {0: 1}
        total = answer = 0
        for x in nums:
            total += x
            answer += freq.get(total - k, 0)
            freq[total] = freq.get(total, 0) + 1
        return answer

import java.util.*;
class Solution {
    public int subarraySum(int[] nums, int k) {
        Map<Integer, Integer> freq = new HashMap<>(); freq.put(0, 1);
        int total = 0, answer = 0;
        for (int x : nums) { total += x; answer += freq.getOrDefault(total - k, 0); freq.put(total, freq.getOrDefault(total, 0) + 1); }
        return answer;
    }
}

class Solution:
    def arrayPairSum(self, nums: list[int]) -> int:
        nums.sort()
        return sum(nums[::2])

import java.util.*;
class Solution {
    public int arrayPairSum(int[] nums) {
        Arrays.sort(nums); int answer = 0;
        for (int i = 0; i < nums.length; i += 2) answer += nums[i];
        return answer;
    }
}

class Solution:
    def findTilt(self, root) -> int:
        tilt = 0
        def total(node):
            nonlocal tilt
            if node is None:
                return 0
            left = total(node.left); right = total(node.right)
            tilt += abs(left - right)
            return node.val + left + right
        total(root)
        return tilt

class Solution {
    private int tilt;
    public int findTilt(TreeNode root) { tilt = 0; sum(root); return tilt; }
    private int sum(TreeNode node) {
        if (node == null) return 0;
        int left = sum(node.left), right = sum(node.right);
        tilt += Math.abs(left - right);
        return node.val + left + right;
    }
}

class Solution:
    def matrixReshape(self, mat: list[list[int]], r: int, c: int) -> list[list[int]]:
        m, n = len(mat), len(mat[0])
        if m * n != r * c:
            return mat
        flat = [x for row in mat for x in row]
        return [flat[i * c:(i + 1) * c] for i in range(r)]

class Solution {
    public int[][] matrixReshape(int[][] mat, int r, int c) {
        int m = mat.length, n = mat[0].length;
        if (m * n != r * c) return mat;
        int[][] out = new int[r][c];
        for (int i = 0; i < m * n; i++) out[i / c][i % c] = mat[i / n][i % n];
        return out;
    }
}
